/**
 * scroll-sequence — el producto gira con el scroll: una secuencia de imágenes
 * (render orbital, video del producto girando, mesa giratoria) en un <canvas>
 * mientras la sección está fijada.
 * Familia: scroll y narrativa · Intensidad 3–4 · 0 deps · Firma posible.
 *
 * Dos modos:
 * - `chapters` (recomendado, con `poses`): el scroll elige el capítulo y el
 *   giro hasta la pose se reproduce solo, a velocidad constante y con fundido.
 * - `scrub` (sin `poses`): el cuadro sigue al scroll con lerp; con pocos
 *   cuadros por tramo se ven saltos al scrollear despacio.
 *
 *   <section data-fx-sequence class="h-[220svh]">
 *     <div class="sticky top-0 h-svh">
 *       <canvas data-fx-canvas></canvas>
 *       <img data-fx-fallback src="frame-001.webp" alt="El producto, de frente">
 *
 * Reduced motion: un solo cuadro (`stillFrame`), sin escuchar el scroll (en vivo).
 * destroy(): saca listeners y observer, corta las cargas, suelta las imágenes
 * y devuelve el canvas y el fallback como estaban.
 */

import { clamp01, createLoop, damp, motionSwitch, part, preserve, progress, bundle, type FxHandle } from '../../core/index';
import { createFramePlayer, frameUrls, loadOrder, type Frames } from '../../lib/frame-player';

/** Capítulo activo: `stops` son las fracciones (0–1) donde empieza cada uno. */
export function chapterAt(p: number, stops: number[]): number {
  let active = 0;
  for (let i = 0; i < stops.length; i++) if (p >= (stops[i] ?? Infinity)) active = i;
  return active;
}

export interface ScrollSequenceOptions {
  frames: Frames;
  canvas?: HTMLCanvasElement | null;
  fallback?: HTMLElement | null;
  /** Tramo del pin que se usa (aire al entrar y salir). */
  range?: [number, number];
  fit?: 'contain' | 'cover';
  /** Cuadro quieto de reduced motion (default: el del medio). */
  stillFrame?: number;
  /** Dónde empieza cada capítulo (fracción del pin). */
  stops?: number[];
  /** Dónde queda la secuencia (0–1) en cada capítulo. Con `poses`, modo capítulos. */
  poses?: number[];
  /** Segundos para recorrer la secuencia entera en modo capítulos. */
  duration?: number;
  onFrame?: (index: number, progress: number) => void;
  onChapter?: (chapter: number) => void;
}

export function createScrollSequence(section: HTMLElement, options: ScrollSequenceOptions): FxHandle {
  const canvas = options.canvas ?? part<HTMLCanvasElement>(section, 'canvas');
  const fallback = options.fallback ?? part(section, 'fallback');
  const urls = frameUrls(options.frames);
  const n = urls.length;
  if (!canvas || !n || !canvas.getContext('2d')) return { destroy() {} };
  const { range = [0, 1], fit = 'contain', stops = [0], poses, duration = 2.4, onFrame, onChapter } = options;

  const player = createFramePlayer({ canvas, urls, fit });
  const still = Math.min(n - 1, Math.max(0, Math.round(options.stillFrame ?? Math.floor(n / 2))));
  const toIndex = (t: number) => Math.round(clamp01(t) * (n - 1));
  const restore = bundle(
    preserve(canvas, { attributes: ['aria-hidden'] }),
    fallback && preserve(fallback, { attributes: ['hidden'] }),
  );
  canvas.setAttribute('aria-hidden', 'true');
  fallback?.setAttribute('hidden', '');
  player.resize();

  let target = 0;
  let value = 0;
  let goal = 0;
  let chapter = -1;
  const paint = () => {
    player.show(clamp01(value) * (n - 1));
    onFrame?.(toIndex(value), poses ? target : value);
  };
  const read = () => {
    const r = section.getBoundingClientRect();
    const p = clamp01(-r.top / Math.max(1, r.height - window.innerHeight));
    target = progress(p, range[0], range[1]);
    const ch = chapterAt(target, stops);
    if (ch !== chapter) {
      chapter = ch;
      onChapter?.(ch);
    }
    goal = poses ? (poses[Math.min(ch, poses.length - 1)] ?? 0) : target;
  };
  const loop = createLoop((dt) => {
    if (poses) {
      const step = dt / duration; // velocidad constante: cada cuadro se ve, a ritmo de video
      value = Math.abs(goal - value) <= step ? goal : value + Math.sign(goal - value) * step;
    } else {
      value = damp(value, goal, 0.0015, dt);
      if (Math.abs(goal - value) < 0.0004) value = goal;
    }
    paint();
    return value !== goal;
  });
  const kick = () => {
    read();
    loop.wake();
  };
  const onResize = () => player.resize();
  addEventListener('resize', onResize, { passive: true });

  let started = false;
  const off = motionSwitch({
    full: () => {
      read();
      value = goal; // al montar no anima: aparece en su pose
      paint();
      if (!started) player.loadWhenNear(section, () => loadOrder(n, toIndex(value)));
      started = true;
      addEventListener('scroll', kick, { passive: true });
      return () => {
        removeEventListener('scroll', kick);
        loop.stop();
      };
    },
    reduced: () => {
      player.show(still);
      onFrame?.(still, 0.5);
      if (!started) player.loadWhenNear(section, () => loadOrder(n, still));
      started = true;
    },
  });

  return {
    destroy() {
      off();
      removeEventListener('resize', onResize);
      player.destroy();
      restore();
    },
  };
}

'use client';

import type { DependencyList, RefObject } from 'react';
import { useFx } from '../../core/react';
import type { FxHandle } from '../../core/types';
import { createScrollSequence, type ScrollSequenceOptions } from './index';

/**
 * Hook de `scroll-sequence`. Monta sobre `ref.current` y destruye al desmontar.
 * Las opciones se leen al montar; pasá `deps` para volver a montar cuando cambien.
 */
export function useScrollSequence<E extends HTMLElement>(
  ref: RefObject<E | null>,
  options: ScrollSequenceOptions,
  deps: DependencyList = [],
): RefObject<FxHandle | null> {
  return useFx(ref, (el) => createScrollSequence(el, options), deps);
}

/**
 * Reproductor de secuencias de imágenes sobre un <canvas>: carga progresiva,
 * dibujo con devicePixelRatio, el cuadro cargado más cercano mientras falta
 * el pedido y fundido entre cuadros vecinos. No decide qué mostrar: eso lo
 * hacen `scroll-sequence` y `turntable`.
 */

import { whenNear } from '../core/index';

/** Orden de carga: primero el cuadro que se va a ver, después cada 8º, cada 4º y el resto. */
export function loadOrder(n: number, first: number): number[] {
  const seen = new Set([first]);
  const out = [first];
  for (const step of [8, 4, 1]) {
    for (let i = 0; i < n; i += step) {
      if (!seen.has(i)) {
        seen.add(i);
        out.push(i);
      }
    }
  }
  return out;
}

export type Frames = string[] | { count: number; src: (i: number) => string };

export const frameUrls = (frames: Frames): string[] =>
  Array.isArray(frames) ? frames.slice() : Array.from({ length: frames.count }, (_, i) => frames.src(i));

export interface FramePlayer {
  readonly count: number;
  /** Posición con decimales: `12.4` funde el 12 con el 13 al 40%. `wrap` = bucle. */
  show(pos: number, wrap?: boolean): void;
  resize(): void;
  /** Empieza a cargar cuando `el` queda a ~1 pantalla. `order` se evalúa al disparar. */
  loadWhenNear(el: Element, order: () => number[]): void;
  destroy(): void;
}

export function createFramePlayer({
  canvas,
  urls,
  fit = 'contain',
  concurrency = 6,
}: {
  canvas: HTMLCanvasElement;
  urls: string[];
  fit?: 'contain' | 'cover';
  concurrency?: number;
}): FramePlayer {
  const n = urls.length;
  const ctx = canvas.getContext('2d');
  let imgs: (HTMLImageElement | null)[] = new Array(n).fill(null);
  const inFlight = new Set<HTMLImageElement>();
  let queue: number[] = [];
  let offNear: (() => void) | null = null;
  let active = 0;
  let dead = false;
  let want = 0;
  let mix = 0;
  let loop = false;
  let drawn = '';

  const nearest = (i: number) => {
    if (imgs[i]) return i;
    for (let d = 1; d < n; d++) {
      if (i - d >= 0 && imgs[i - d]) return i - d;
      if (i + d < n && imgs[i + d]) return i + d;
    }
    return -1;
  };
  const paintImg = (img: HTMLImageElement, alpha: number) => {
    if (!ctx) return;
    const { width: W, height: H } = canvas;
    const s = (fit === 'cover' ? Math.max : Math.min)(W / img.naturalWidth, H / img.naturalHeight);
    const dw = img.naturalWidth * s;
    const dh = img.naturalHeight * s;
    ctx.globalAlpha = alpha;
    ctx.drawImage(img, (W - dw) / 2, (H - dh) / 2, dw, dh);
    ctx.globalAlpha = 1;
  };
  const draw = () => {
    if (!ctx) return;
    const i = nearest(want);
    if (i < 0) return; // sin cuadros todavía: queda lo que hubiera
    const next = loop ? (i + 1) % n : i + 1;
    const nextImg = next < n ? imgs[next] : null;
    const f = i === want && mix > 0.02 && nextImg ? Math.round(mix * 32) / 32 : 0;
    const key = `${i}:${f}`;
    if (key === drawn) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Base opaca y siguiente encima con alfa: el objeto nunca se vuelve translúcido.
    paintImg(imgs[i] as HTMLImageElement, 1);
    if (f && nextImg) paintImg(nextImg, f);
    drawn = key;
  };
  const resize = () => {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.round(canvas.clientWidth * dpr);
    const h = Math.round(canvas.clientHeight * dpr);
    if (w !== canvas.width || h !== canvas.height) {
      canvas.width = w;
      canvas.height = h;
      drawn = '';
    }
    draw();
  };
  const pump = () => {
    while (!dead && active < concurrency && queue.length) {
      const i = queue.shift() as number;
      const img = new Image();
      img.decoding = 'async';
      img.src = urls[i] as string;
      inFlight.add(img);
      active++;
      img
        .decode()
        .then(() => {
          if (dead) return;
          imgs[i] = img;
          draw();
        })
        .catch(() => {}) // un cuadro roto no corta nada: se usa el vecino
        .finally(() => {
          inFlight.delete(img);
          active--;
          pump();
        });
    }
  };

  return {
    count: n,
    show(pos, wrap = false) {
      loop = wrap;
      const p = wrap ? ((pos % n) + n) % n : Math.min(n - 1, Math.max(0, pos));
      want = Math.floor(p);
      mix = p - want;
      draw();
    },
    resize,
    loadWhenNear(el, order) {
      offNear = whenNear(el, () => {
        queue = order();
        pump();
      });
    },
    destroy() {
      dead = true;
      offNear?.();
      queue = [];
      for (const img of inFlight) img.src = '';
      for (const img of imgs) if (img) img.src = '';
      inFlight.clear();
      imgs = [];
      ctx?.clearRect(0, 0, canvas.width, canvas.height);
    },
  };
}
